#include <IQM/hdrvdp3/fftw_single_provider.h>
#include <fstream>
#include <iostream>
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("Usage: fftw.dll fresh-out");std::filesystem::path out=argv[2];if(std::filesystem::exists(out)||!std::filesystem::create_directories(out))throw std::runtime_error("Fresh output required");IQM::HDRVDP3::FFTWProviderSingle api(argv[1]);using C=IQM::HDRVDP3::FFTWProviderSingle::Complex;auto make=api.symbol<void*(*)(int,C*,C*,int,unsigned)>("fftwf_plan_dft_1d");auto flops=api.symbol<void(*)(void*,double*,double*,double*)>("fftwf_flops");auto text=api.symbol<char*(*)(void*)>("fftwf_sprint_plan");std::ofstream report(out/"flops.jsonl");for(int n:{24,96,384})for(int sign:{-1,1}){IQM::HDRVDP3::FFTWProviderSingle::Memory src(api,n*8),dst(api,n*8);api.forget();auto p=make(n,static_cast<C*>(src.data),static_cast<C*>(dst.data),sign,82);if(!p)throw std::runtime_error("Plan");double a,m,f;flops(p,&a,&m,&f);char* printed=text(p);std::ofstream(out/(std::to_string(n)+"_"+std::to_string(sign)+".plan.txt"))<<printed;report<<"{\"n\":"<<n<<",\"sign\":"<<sign<<",\"adds\":"<<a<<",\"muls\":"<<m<<",\"fmas\":"<<f<<"}\n";std::cout<<n<<" sign="<<sign<<" add="<<a<<" mul="<<m<<" fma="<<f<<std::endl;api.destroy(p);}return 0;}catch(const std::exception& e){std::cerr<<e.what()<<std::endl;return 1;}}
